-- kroger-prescription-drug-prices-class-action-settlement
do $$
declare
  v_lawsuit uuid;
  v_spec_version integer;
  v_policy_version integer;
begin
  select id into v_lawsuit from public.lawsuits where slug = 'kroger-prescription-drug-prices-class-action-settlement';
