Kroger for insured prescriptions in the class period, if you are stating an amount","help":null,"type":"text","required":false,"options":null,"validation":null,"visible_when":null,"tiers":null,"health_flag":false},{"key":"notice_id","official_label":"Notice ID (if listed on your notice)","help":null,"type":"notice_id","required":false,"options":null,"validation":null,"visible_when":null,"tiers":null,"health_flag":false}],"benefit_tiers":[],"payout_options":[{"value":"check","official_label":"Check"},{"value":"other","official_label":"Other payment method listed on the official form"}],"form_field_order":["member.first_name","member.last_name","member.legal_name","member.email","member.phone","member.address.line1","member.address.line2","member.address.city","member.address.state","member.address.zip","answers.class_member","answers.claimed_amount","answers.notice_id","payout_method"],"jev_rules":[],"desk_notes":"Angeion submit-claim. 2026-11-25 dry-run: after the No-notice path the form asks for an email and “Send code” (one-time login). Not fillable from profile data. Owner must not approve until a no-login identity form exists. Supporting documents only if the total amount claimed is $8,000 or more. Deadline December 21, 2026. Never submit a test identity."}'::jsonb);
    raise notice 'inserted spec draft kroger-prescription-drug-prices-class-action-settlement v%', v_spec_version;
  end if;
  if exists (
    select 1 from public.filing_policies
    where lawsuit_id = v_lawsuit and status in ('draft', 'approved')
  ) then
    raise notice 'skip policy kroger-prescription-drug-prices-class-action-settlement: a live policy already exists';
  else
    select coalesce(max(version), 0) + 1 into v_policy_version
      from public.filing_policies where lawsuit_id = v_lawsuit;
    insert into public.filing_policies (
      lawsuit_id, version, agent_filing, channels, allowed_states, sources_reviewed, notes
    ) values (
      v_lawsuit,
      v_policy_version,
      'allowed',
      '[{"type":"filing_desk","enabled":true,"daily_capacity":10,"sla_business_days":2,"min_days_before_deadline":5,"accepts_documents":false,"instructions":"Fill the official form at https://www.krogersavingsclubsettlement.com/submit-claim from the packet. Never submit a test identity. Stop if a captcha, login, or proof upload appears."}]'::jsonb,
      '["AL","AK","AZ","AR","CA","CO","CT","DE","DC","FL","GA","HI","ID","IL","IN","IA","KS","KY","LA","ME","MD","MA","MI","MN","MS","MO","MT","NE","NV","NH","NJ","NM","NY","NC","ND","OH","OK","OR","PA","RI","SC","SD","TN","TX","UT","VT","VA","WA","WV","WI","WY"]'::jsonb,
